async function fetchJson(url,timeout=15000){if(httpRequests>=HTTP_CAP)throw Error("http-request-cap");httpRequests++;const c=new AbortController(),timer=setTimeout(()=>c.abort(),timeout);try{const r=await fetch(url,{headers:{accept:"application/json"},signal:c.signal});if(!r.ok)throw Error("http-unavailable");const text=await r.text();if(text.length>8_000_000)throw Error("http-response-cap");return JSON.parse(text)}finally{clearTimeout(timer)}}
async function rpcUrl(url,method,params,timeout=18000){if(rpcRequests>=RPC_CAP)throw Error("rpc-request-cap");rpcRequests++;const c=new AbortController(),timer=setTimeout(()=>c.abort(),timeout);try{const r=await fetch(url,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({jsonrpc:"2.0",id:rpcRequests,method,params}),signal:c.signal});const j=await r.json();if(j.error||j.result===undefined)throw Error("rpc-unavailable");return j.result}finally{clearTimeout(timer)}}
async function rpc(method,params,seed=0,retries=2){let last;for(let round=0;round<retries;round++)for(let i=0;i<RPCS.length;i++)try{return await rpcUrl(RPCS[(seed+i+round)%RPCS.length],method,params)}catch(e){last=e;await sleep(80*(round+1))}throw last||Error("rpc")}
function normalizeAbi(x){const abi=Array.isArray(x)?x:JSON.parse(x);return abi}
function eventSchema(item){return {name:item.name,signature:`${item.name}(${item.inputs.map(x=>x.type).join(",")})`,topic:ethers.id(`${item.name}(${item.inputs.map(x=>x.type).join(",")})`),inputs:item.inputs.map(x=>({name:x.name||null,type:x.type,indexed:!!x.indexed}))}}
