async function getLogsAdaptive(from,to,rows,failures,depth=0){if(from>to)return;try{const logs=await rpc("eth_getLogs",[{address:VAULT,fromBlock:hex(from),toBlock:hex(to)}],depth,3);rows.push({fromBlock:from,toBlock:to,eventCount:logs.length,logs});return}catch{}if(from===to||depth>=14){failures.push({fromBlock:from,toBlock:to,errorClass:"public-log-query-unavailable"});return}const mid=Math.floor((from+to)/2);await getLogsAdaptive(from,mid,rows,failures,depth+1);await getLogsAdaptive(mid+1,to,rows,failures,depth+1)}
