function sanitizeValue(input,value,eventName){if(input.type==="address"){const a=String(value).toLowerCase();if(eventName==="Upgraded")return {contractAddress:a};return {identityCommitment:commit(a)}}if(input.type.endsWith("[]"))return Array.from(value).map(v=>typeof v==="bigint"?v.toString():String(v));if(typeof value==="bigint")return value.toString();if(typeof value==="boolean")return value;return String(value)}
